{"output":"1\t\"\"\"汇率查询：JPY→CNY。\n2\t\n3\t主源 open.er-api.com/v6（免 key）→ 备源 exchangerate-api.com/v4 → 本地缓存 → 内置基准 0.04224。\n4\t用法：\n5\t  python3 exchange_rate.py\n6\t  python3 exchange_rate.py --baseline   # 直接取内置基准，不打网络\n7\t\"\"\"\n8\timport argparse\n9\timport json\n10\timport os\n11\t\n12\tfrom _common import http_request, JsbError\n13\t\n14\tFALLBACK_RATE = 0.04224  # 实测基准（k780）\n15\t\n16\tSOURCES = [\n17\t    (\"open.er-api.com/v6\", \"https://open.er-api.com/v6/latest/JPY\", \"rates\"),\n18\t    (\"exchangerate-api.com/v4\", \"https://api.exchangerate-api.com/v4/latest/JPY\", \"rates\"),\n19\t]\n20\t\n21\t\n22\tdef _cache_file():\n23\t    base = os.environ.get(\"JSB_CACHE_DIR\", os.path.expanduser(\"~/.japan-shopping-buddy\"))\n24\t    return os.path.join(base, \"exchange_rate.json\")\n25\t\n26\t\n27\tdef _read_cache():\n28\t    try:\n29\t        with open(_cache_file(), \"r\", encoding=\"utf-8\") as f:\n30\t            return json.load(f)\n31\t    except Exception:\n32\t        return None\n33\t\n34\t\n35\tdef _write_cache(record):\n36\t    try:\n37\t        os.makedirs(os.path.dirname(_cache_file()), exist_ok=True)\n38\t        with open(_cache_file(), \"w\", encoding=\"utf-8\") as f:\n39\t            json.dump(record, f, ensure_ascii=False, indent=2)\n40\t    except Exception:\n41\t        pass\n42\t\n43\t\n44\tdef fetch():\n45\t    \"\"\"查询汇率；任何网络异常都降级到内置基准，绝不抛异常。\"\"\"\n46\t    errors = []\n47\t    for source, url, rates_key in SOURCES:\n48\t        try:\n49\t            # 汇率 API 属全球 CDN，无需日本代理，直连即可\n50\t            status, text = http_request(\"GET\", url, use_proxy=False, timeout=12)\n51\t            if status == 200:\n52\t                data = json.loads(text)\n53\t                rate = data.get(rates_key, {}).get(\"CNY\")\n54\t                if rate:\n55\t                    return {\n56\t                        \"base\": \"JPY\",\n57\t                        \"target\": \"CNY\",\n58\t                        \"rate\": float(rate),\n59\t                        \"source\": source,\n60\t                        \"time_utc\": data.get(\"time_last_update_utc\") or data.get(\"date\"),\n61\t                        \"is_fallback\": False,\n62\t                    }\n63\t            errors.append(f\"{source} -> HTTP {status}\")\n64\t        except Exception as e:  # noqa: BLE001\n65\t            errors.append(f\"{source} -> {e}\")\n66\t\n67\t    cached = _read_cache()\n68\t    if cached and cached.get(\"rate\"):\n69\t        cached[\"is_fallback\"] = True\n70\t        cached[\"fallback_reason\"] = \"network_failed: \" + \"; \".join(errors)\n71\t        return cached\n72\t\n73\t    return {\n74\t        \"base\": \"JPY\",\n75\t        \"target\": \"CNY\",\n76\t        \"rate\": FALLBACK_RATE,\n77\t        \"source\": \"builtin_baseline\",\n78\t        \"is_fallback\": True,\n79\t        \"fallback_reason\": \"network_failed: \" + \"; \".join(errors),\n80\t    }\n81\t\n82\t\n83\tdef main():\n84\t    ap = argparse.ArgumentParser(description=\"查询 JPY→CNY 汇率\")\n85\t    ap.add_argument(\"--baseline\", action=\"store_true\", help=\"仅返回内置基准，不打网络\")\n86\t    args = ap.parse_args()\n87\t\n88\t    if args.baseline:\n89\t        result = {\n90\t            \"base\": \"JPY\", \"target\": \"CNY\", \"rate\": FALLBACK_RATE,\n91\t            \"source\": \"builtin_baseline\", \"is_fallback\": True,\n92\t        }\n93\t    else:\n94\t        try:\n95\t            result = fetch()\n96\t        except JsbError as e:\n97\t            print(json.dumps({\"error\": str(e)}, ensure_ascii=False, indent=2))\n98\t            raise SystemExit(1)\n99\t        if not result.get(\"is_fallback\") and result.get(\"rate\"):\n100\t            _write_cache(result)\n101\t\n102\t    print(json.dumps(result, ensure_ascii=False, indent=2))\n103\t\n104\t\n105\tif __name__ == \"__main__\":\n106\t    main()"}
